import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.CZo9GF0W.js";const g=JSON.parse('{"title":"13 — Release & Publishing","description":"","frontmatter":{},"headers":[],"relativePath":"13-RELEASE.md","filePath":"13-RELEASE.md","lastUpdated":1789060268000}'),n={name:"13-RELEASE.md"};function o(r,e,h,l,d,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="_13-—-release-publishing" tabindex="-1">13 — Release &amp; Publishing <a class="header-anchor" href="#_13-—-release-publishing" aria-label="Permalink to &quot;13 — Release &amp; Publishing&quot;">​</a></h1><p>Phase 10. The pipeline is built and verified in CI; what remains at each release is an account, two tokens, and a decision.</p><h2 id="_1-one-time-setup" tabindex="-1">1. One-time setup <a class="header-anchor" href="#_1-one-time-setup" aria-label="Permalink to &quot;1. One-time setup&quot;">​</a></h2><h3 id="publisher-accounts" tabindex="-1">Publisher accounts <a class="header-anchor" href="#publisher-accounts" aria-label="Permalink to &quot;Publisher accounts&quot;">​</a></h3><p><strong>Visual Studio Marketplace.</strong> Create a publisher at <a href="https://marketplace.visualstudio.com/manage" target="_blank" rel="noreferrer">https://marketplace.visualstudio.com/manage</a>, signed in with a Microsoft account. The publisher id must match <code>publisher</code> in <code>packages/extension/package.json</code> — currently <code>DipeshShrestha</code>. Changing it later means a new extension identity and losing every install, so it is worth being sure now.</p><p><strong>Open VSX.</strong> Sign in at <a href="https://open-vsx.org" target="_blank" rel="noreferrer">https://open-vsx.org</a> with GitHub, agree to the publisher agreement, and create a namespace with the same name. Open VSX will not accept a publish into a namespace nobody has claimed.</p><h3 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h3><p><strong><code>VSCE_PAT</code></strong> — an Azure DevOps personal access token for the organization backing the publisher, scoped to <strong>Marketplace → Manage</strong>, with <strong>All accessible organizations</strong> selected. A token scoped to one organization fails with an unhelpful authentication error.</p><p><strong><code>OVSX_PAT</code></strong> — from the Open VSX profile page.</p><p>Both go in the GitHub repository under <strong>Settings → Secrets and variables → Actions</strong>, as secrets of the <strong><code>marketplace</code></strong> environment, not as repository secrets. The environment is what makes a publish require a reviewer.</p><h3 id="the-environment-gate" tabindex="-1">The environment gate <a class="header-anchor" href="#the-environment-gate" aria-label="Permalink to &quot;The environment gate&quot;">​</a></h3><p>Create an environment named <code>marketplace</code> (<strong>Settings → Environments</strong>) and add yourself as a required reviewer. <code>.github/workflows/release.yml</code> targets it, so a tag alone never publishes: the job waits for an approval.</p><h2 id="_2-cutting-a-release" tabindex="-1">2. Cutting a release <a class="header-anchor" href="#_2-cutting-a-release" aria-label="Permalink to &quot;2. Cutting a release&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Bump the version in packages/extension/package.json.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    An ODD minor is a pre-release; an EVEN minor is stable. This is the</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    convention VS Code itself documents, and release.yml reads it.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Update packages/extension/CHANGELOG.md.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Commit on main, then tag it.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;chore(release): prepare 0.2.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:tag</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Push the tag. This is the publish.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span></span></code></pre></div><p><code>pnpm release:tag</code> reads the version out of the manifest, so the tag and the manifest cannot disagree - which is the check <code>release.yml</code> refuses on. It copies that version&#39;s changelog section into an annotated tag, so <code>git show v0.2.0</code> says what shipped without asking a marketplace, and it refuses to tag a dirty tree, a version with no changelog entry, or a name that already points somewhere else. It never pushes: pushing is what publishes.</p><p>Tagging a release already made - one from before the tag was part of this - takes the commit that bumped the manifest:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --at</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # reads that commit&#39;s own manifest and changelog</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">A pushed tag is a publish</p><p><code>release.yml</code> fires on <code>v*</code>. Pushing a backfilled tag for an old version starts a real release of that version, so historical tags are worth keeping local unless you actually want to republish one.</p></div><p>The workflow then:</p><ol><li><strong>verify</strong> — <code>pnpm run verify</code>, <code>pnpm run build</code>, <code>pnpm run test:bench</code>, against the exact commit being released. A tag that skips verification is a tag nobody can trust.</li><li><strong>package</strong> — checks the tag matches the manifest version and refuses if they disagree, builds the VSIX, and asserts what is inside it: the extension bundle, both WASM runtimes, the snippets, the walkthrough pages, and <em>nothing</em> from <code>src/</code> or <code>node_modules/</code>.</li><li><strong>publish</strong> — waits for approval, then Marketplace, Open VSX, and a GitHub release with the VSIX attached.</li></ol><p><code>workflow_dispatch</code> runs the same thing without a tag, choosing the channel by hand.</p><h3 id="what-the-vsix-check-is-for" tabindex="-1">What the VSIX check is for <a class="header-anchor" href="#what-the-vsix-check-is-for" aria-label="Permalink to &quot;What the VSIX check is for&quot;">​</a></h3><p>The webview build empties <code>packages/extension/media</code> on every run, so a hand-written file placed there vanishes from the VSIX while everything still builds and every test passes. The content assertions in <code>release.yml</code> and in <code>test/unit/manifest.test.ts</code> are what catch it.</p><h2 id="_3-the-listing" tabindex="-1">3. The listing <a class="header-anchor" href="#_3-the-listing" aria-label="Permalink to &quot;3. The listing&quot;">​</a></h2><p>Both marketplaces render <code>packages/extension/README.md</code>. <code>vsce</code> rewrites relative image links to absolute <code>raw.githubusercontent.com</code> URLs using the <code>repository</code> field, so demo assets must be <strong>committed</strong> but need not be <strong>shipped</strong> — <code>resources/demo/**</code> is in <code>.vscodeignore</code> for that reason.</p><p>Listing fields live in <code>packages/extension/package.json</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Why it is what it is</th></tr></thead><tbody><tr><td><code>displayName</code>, <code>description</code></td><td>The search result. The description names the six engines because that is what people search for.</td></tr><tr><td><code>categories</code></td><td>Data Science, Programming Languages, Notebooks, Visualization, Formatters. There is no Database category.</td></tr><tr><td><code>keywords</code></td><td>The leading entries rank highest; engines first, then the words that describe the tool.</td></tr><tr><td><code>icon</code>, <code>galleryBanner</code></td><td><code>resources/icon.png</code> on the dark banner.</td></tr><tr><td><code>pricing</code></td><td><code>Free</code>.</td></tr><tr><td><code>qna</code></td><td>Points at GitHub Discussions rather than the Marketplace&#39;s own Q&amp;A, which nobody watches.</td></tr><tr><td><code>preview</code></td><td><code>true</code> until 1.0. Shows the Preview badge.</td></tr><tr><td><code>capabilities</code></td><td>Untrusted-workspace and virtual-workspace support, both <code>limited</code> and both honest about what does not work.</td></tr></tbody></table><h3 id="before-the-first-publish" tabindex="-1">Before the first publish <a class="header-anchor" href="#before-the-first-publish" aria-label="Permalink to &quot;Before the first publish&quot;">​</a></h3><ul><li>[ ] Publisher created on both marketplaces, ids matching the manifest</li><li>[ ] <code>VSCE_PAT</code> and <code>OVSX_PAT</code> in the <code>marketplace</code> environment</li><li>[ ] <code>marketplace</code> environment has a required reviewer</li><li>[ ] GitHub <strong>private vulnerability reporting</strong> enabled (Settings → Code security), since <code>SECURITY.md</code> points people at it</li><li>[ ] Discussions enabled, since <code>qna</code> and the issue-template chooser point there</li><li>[ ] Demo clips recorded (below) and the <code>&lt;img&gt;</code> block in <code>packages/extension/README.md</code> uncommented</li><li>[ ] <code>pnpm run package</code> inspected locally: install the VSIX in a clean profile and connect to something in under 30 seconds, guided only by the README</li></ul><h2 id="_4-demo-clips" tabindex="-1">4. Demo clips <a class="header-anchor" href="#_4-demo-clips" aria-label="Permalink to &quot;4. Demo clips&quot;">​</a></h2><p>Five clips, in <code>packages/extension/resources/demo/</code>. They are the listing&#39;s real copy — most people scroll the images and read nothing.</p><p><strong>Rules for all of them.</strong> 1280×800 window, dark theme, editor font at 16px so it reads at listing size. No real hostnames, no real data — use <code>pnpm run db:up</code>, which seeds every engine. Under 8 seconds and under 2 MB each; if it does not fit, the clip is doing too much. No cursor teleporting: move, pause, click. Start on a clean editor, end on the result, no trailing idle frames.</p><table tabindex="0"><thead><tr><th>File</th><th>Scene</th></tr></thead><tbody><tr><td><code>connect.gif</code></td><td>Add Connection → fill host/database/user → <strong>Test Connection</strong> → green → save → the tree expands to a table. Shows: the form is per-engine, secrets go to the keychain, it works before you have typed any SQL.</td></tr><tr><td><code>grid.gif</code></td><td>Open Data on a table → filter a column → edit a cell → <strong>Apply</strong> shows the exact <code>UPDATE</code> with its key → confirm → the row updates. Shows: the SQL is never hidden, edits are staged.</td></tr><tr><td><code>query.gif</code></td><td>Type <code>select … from ord</code> → completion offers the table → alias-aware column completion → run → results, timing, a streamed notice → cancel a slow one. Shows: real intelligence, real cancellation.</td></tr><tr><td><code>plan.gif</code></td><td><strong>Explain</strong> on a join → the plan diagram → hover a flagged node and read the reason. Shows: the plan view is a diagnosis, not a dump.</td></tr><tr><td><code>erd.gif</code></td><td><strong>Show Schema Diagram</strong> → the FK graph lays out → drag a table → filter to neighbours. Shows: the schema tooling exists.</td></tr></tbody></table><p>Record with any screen recorder; convert with <code>ffmpeg</code> + <code>gifski</code> for a small palette-optimised file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffmpeg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect.mov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fps=15,scale=1280:-1:flags=lanczos&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yuv4mpegpipe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gifski</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect.gif</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 15</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quality</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre></div><h2 id="_5-pre-release-channel" tabindex="-1">5. Pre-release channel <a class="header-anchor" href="#_5-pre-release-channel" aria-label="Permalink to &quot;5. Pre-release channel&quot;">​</a></h2><p>An odd minor version publishes to the Marketplace pre-release channel. Users who opt in get it; everyone else stays on the last even minor. Open VSX has no pre-release channel, so the same artifact is published there and the odd minor is the only signal.</p><p>Keep the two channels&#39; version lines apart: <code>0.3.x</code> pre-release, <code>0.4.0</code> the stable release of that work.</p><h2 id="_6-open-questions" tabindex="-1">6. Open questions <a class="header-anchor" href="#_6-open-questions" aria-label="Permalink to &quot;6. Open questions&quot;">​</a></h2><ul><li><strong>Signed VSIX.</strong> <code>vsce</code> supports signing; it needs a certificate and a decision about where the key lives. Not blocking a first publish.</li><li><strong><code>semantic-release</code>.</strong> P10-T5 asks for it. The version is currently bumped by hand and the tag/manifest check in <code>release.yml</code> catches the mistake that makes. Worth doing once the release cadence is regular enough to be annoying.</li><li><strong>Telemetry.</strong> <code>pitta.telemetry.enabled</code> exists, defaults to false, and has no implementation and no transport behind it. S7.1 asks for an opt-in flow and a documented event list; there is currently no backend to send anything to. Either build the transport or drop the setting — leaving a setting that promises collection that does not happen is the one option that is wrong.</li></ul>`,40)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
